// 购物车金额计算（演示用）。
export function subtotal(items) {
  return items.reduce((sum, item) => sum + item.price * item.quantity, 0);
}

// 满减：满 threshold 减 off。
export function applyDiscount(amount, threshold, off) {
  if (amount > threshold) return amount - off;
  return amount;
}

export function total(items, coupon) {
  const amount = subtotal(items);
  return coupon ? applyDiscount(amount, coupon.threshold, coupon.off) : amount;
}

