import { test } from "node:test";
import assert from "node:assert/strict";
import { subtotal, total } from "../src/cart.js";

test("小计按单价乘数量累加", () => {
  assert.equal(subtotal([{ price: 10, quantity: 2 }, { price: 5, quantity: 1 }]), 25);
});

test("正好满额也应该减", () => {
  assert.equal(total([{ price: 100, quantity: 1 }], { threshold: 100, off: 20 }), 80);
});

